mapper.select:
SELECT c.clean_content AS evaluationText FROM clean_interaction_result c WHERE c.clean_content IS NOT NULL AND c.clean_content != ''
AND c.clean_time >= #{startTime}
AND c.clean_time <= #{endTime}
ORDER BY c.clean_time DESC LIMIT 500

SELECT r.robot_id AS robotId, r.location_area AS locationArea, r.specific_location AS specificLocation, r.coordinate_x AS coordinateX, r.coordinate_y AS coordinateY, r.move_speed AS moveSpeed, r.status_desc AS statusDesc FROM robot_position_history r INNER JOIN ( SELECT robot_id, MAX(record_time) AS max_time FROM robot_position_history
AND tenant_id = #{tenantId}
GROUP BY robot_id ) latest ON r.robot_id = latest.robot_id AND r.record_time = latest.max_time
AND tenant_id = #{tenantId}

SELECT status, COUNT(*) AS count FROM robots
AND tenant_id = #{tenantId}
GROUP BY status

SELECT t.id, t.name, t.robot_id AS robotId, t.status, t.scheduled_time AS scheduledTime, t.priority, COUNT(ts.id) AS totalSteps, SUM(CASE WHEN ts.status = 2 THEN 1 ELSE 0 END) AS completedSteps FROM tm_task t LEFT JOIN tm_task_step ts ON ts.task_id = t.id WHERE 1=1
AND t.tenant_id = #{tenantId}
AND t.create_time >= #{startTime}
AND t.create_time <= #{endTime}
AND t.status IN (0, 1)
GROUP BY t.id, t.name, t.robot_id, t.status, t.scheduled_time, t.priority ORDER BY t.priority DESC, t.scheduled_time ASC
LIMIT #{limit} OFFSET #{offset}

SELECT rg.id, rg.name, rg.description, COUNT(r.id) AS totalCount, COUNT(CASE WHEN r.status = 1 THEN 1 END) AS onlineCount FROM robot_groups rg LEFT JOIN robots r ON r.group_id = rg.id
AND r.tenant_id = #{tenantId}
WHERE rg.tenant_id = #{tenantId}
GROUP BY rg.id, rg.name, rg.description ORDER BY rg.id ASC
